1892	static void music_play(uint32_t id)
1893	{
1894	    if (dm_track_count == 0) return;
1895	    if (id >= dm_track_count) id = 0;
1896	    music_track_id = id;
1897	    music_inited = true;
1898	    music_state_save(music_track_id);
1899	    music_update_track_info();
1900	    music_audio_start(dm_tracks[id].path);
1901	    music_resume();
1902	}
1903	
1904	static void music_resume(void)
1905	{
1906	    music_playing = true;
1907	    /* 音乐后台化（2026-08-08）：HOME 小组件 + standby 控件常驻，播放图标同步更新。 */
1908	    if (home_music_play_icon)
1909	        lv_label_set_text(home_music_play_icon, LV_SYMBOL_PAUSE);
1910	    if (standby_music_play_icon)
1911	        lv_label_set_text(standby_music_play_icon, LV_SYMBOL_PAUSE);
1912	    /* 自动连播在子页面关闭后仍会走到这里，
1913	     * UI 对象可能为 NULL（close_subpage 已置空）——判空保护。 */
1914	    if (music_play_btn)
1915	        lv_obj_add_state(music_play_btn, LV_STATE_CHECKED);
1916	    if (music_play_icon) {
1917	        lv_label_set_text(music_play_icon, LV_SYMBOL_PAUSE);
1918	        /* Icon is a child label: LV_STATE_CHECKED belongs to the button, not the
1919	         * icon, so a CHECKED style on the icon never applies. Switch its color
1920	         * here explicitly — white pause symbol on the blue gradient fill. */
1921	        lv_obj_set_style_text_color(music_play_icon, lv_color_hex(0xFFFFFF), 0);
1922	    }
1923	    if (g_music_timer) lv_timer_resume(g_music_timer);
1924	    music_audio_resume();
1925	}
