1931	    if (home_music_play_icon)
1932	        lv_label_set_text(home_music_play_icon, LV_SYMBOL_PLAY);
1933	    if (standby_music_play_icon)
1934	        lv_label_set_text(standby_music_play_icon, LV_SYMBOL_PLAY);
