1946	static void music_album_next(bool next)
1947	{
1948	    if (dm_track_count == 0) return;
1949	    if (next) {
1950	        music_track_id = (music_track_id + 1) % dm_track_count;
1951	    } else {
1952	        music_track_id =
1953	            (music_track_id == 0) ? dm_track_count - 1 : music_track_id - 1;
1954	    }
1955	    music_play(music_track_id);
1956	}
