1085	    {
1086	        const char *base = scan_dirs[di];
1087	
1088	        dir = opendir(base);
1089	        if (dir == NULL)
1090	            continue;
1091	
1092	        while ((ent = readdir(dir)) != NULL && count < DM_MAX_TRACKS)
1093	        {
1094	            const char *dot = strrchr(ent->d_name, '.');
1095	            int i, ok = 0;
1096	
1097	            if (dot == NULL || dot == ent->d_name)
1098	                continue;
1099	
1100	            for (i = 0; i < 5; i++)
1101	            {
1102	                if (strcasecmp(dot, supported[i]) == 0)
